create table if not exists admin_reset_logs(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id) on delete cascade,admin_user_id uuid not null references auth.users(id),scope text not null check(scope in('ALL_CLAIMS')),affected_count int not null default 0,reason text not null check(char_length(trim(reason)) between 3 and 300),created_at timestamptz not null default now());
alter table admin_reset_logs enable row level security;revoke all on admin_reset_logs from anon,authenticated;
create index if not exists idx_admin_reset_logs_campaign_created on admin_reset_logs(campaign_id,created_at desc);

create or replace function admin_reset_claims(p_campaign text,p_reason text,p_admin_user uuid,p_confirmation text) returns jsonb language plpgsql security definer set search_path=public as $$declare c campaigns;affected int;begin if p_confirmation<>'RESET CLAIMS' then raise exception 'CONFIRMATION_REQUIRED';end if;if char_length(trim(p_reason))<3 then raise exception 'REASON_REQUIRED';end if;if not exists(select 1 from admin_users where user_id=p_admin_user)then raise exception 'ADMIN_FORBIDDEN';end if;select * into c from campaigns where code=p_campaign for update;if not found then raise exception 'CAMPAIGN_NOT_FOUND';end if;with target as(select id,prize_unit_id from spins where campaign_id=c.id and status='CLAIMED'for update),updated_spins as(update spins s set status='AWARDED',claimed_at=null,claim_web_url=null,sheet_sync_status='PENDING',sheet_sync_error=null from target t where s.id=t.id returning s.prize_unit_id),updated_units as(update prize_units pu set status='AWARDED' from updated_spins u where pu.id=u.prize_unit_id and pu.status='CLAIMED'returning pu.id)select count(*)::int into affected from updated_units;insert into admin_reset_logs(campaign_id,admin_user_id,scope,affected_count,reason)values(c.id,p_admin_user,'ALL_CLAIMS',affected,trim(p_reason));return jsonb_build_object('ok',true,'affected',affected,'scope','ALL_CLAIMS');end$$;
revoke all on function admin_reset_claims(text,text,uuid,text) from public,anon,authenticated;grant execute on function admin_reset_claims(text,text,uuid,text) to service_role;
